import os
import subprocess
import re
from flask import Flask, request, jsonify

app = Flask(__name__)

# Configuration
ALLOWED_EXTENSIONS = ['.pdf', '.docx', '.xlsx', '.pptx']
UPLOAD_DIR = '/var/lib/app/uploads'
CONVERT_BIN = '/usr/bin/libreoffice'

def sanitize_filename(filename):
    """Remove path traversal attempts"""
    filename = os.path.basename(filename)
    filename = re.sub(r'[^a-zA-Z0-9._-]', '_', filename)
    return filename

def validate_extension(filename):
    ext = os.path.splitext(filename)[1].lower()
    return ext in ALLOWED_EXTENSIONS

@app.route('/api/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    if not uploaded.filename:
        return jsonify({'error': 'Empty filename'}), 400

    if not validate_extension(uploaded.filename):
        return jsonify({'error': 'Invalid file type'}), 400

    safe_name = sanitize_filename(uploaded.filename)
    input_path = os.path.join(UPLOAD_DIR, safe_name)
    uploaded.save(input_path)

    # Get optional output format from user
    output_format = request.form.get('format', 'pdf')

    # Build conversion command
    cmd = f'{CONVERT_BIN} --headless --convert-to {output_format} --outdir {UPLOAD_DIR} {input_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=UPLOAD_DIR
        )

        if result.returncode != 0:
            return jsonify({'error': 'Conversion failed', 'details': result.stderr.decode()[:200]}), 500

        output_name = os.path.splitext(safe_name)[0] + '.' + output_format.split(':')[0]
        output_path = os.path.join(UPLOAD_DIR, output_name)

        if os.path.exists(output_path):
            return jsonify({'status': 'success', 'output': output_name}), 200
        else:
            return jsonify({'error': 'Output file not generated'}), 500

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500
    finally:
        # Cleanup input file
        if os.path.exists(input_path):
            os.unlink(input_path)

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'}), 200

@app.route('/api/formats', methods=['GET'])
def list_formats():
    """List supported output formats"""
    return jsonify({
        'input': ALLOWED_EXTENSIONS,
        'output': ['pdf', 'docx', 'html', 'txt', 'csv']
    })

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
